import UIKit
enum Section: Hashable { case plants, favorites }
struct Plant {
    let id: Int
    var title: String
}
enum SnapshotError: Error { case duplicateID(Int) }
func checkedIDs(_ plants: [Plant]) throws -> [Int] {
    var seen = Set<Int>()
    for plant in plants {
        guard seen.insert(plant.id).inserted else {
            throw SnapshotError.duplicateID(plant.id)
        }
    }
    return plants.map { $0.id }
}
func makeSnapshot(
    _ plants: [Plant]
) throws -> NSDiffableDataSourceSnapshot<Section, Int> {
    let ids = try checkedIDs(plants)
    var snapshot = NSDiffableDataSourceSnapshot<Section, Int>()
    snapshot.appendSections([.plants])
    snapshot.appendItems(ids, toSection: .plants)
    return snapshot
}
let plants = [Plant(id: 71, title: "Фикус"), Plant(id: 71, title: "Фикус")]
do {
    _ = try makeSnapshot(plants)
    assertionFailure("Повтор не обнаружен")
} catch SnapshotError.duplicateID(let id) {
    assert(id == 71)
} catch { assertionFailure("Другая ошибка") }

Ошибка обнаружена до создания недопустимого снимка. Swift catch обрабатывает наш Error, не внутреннее исключение UIKit.

